config.script:
logger = system.util.getLogger("StationDebug")

def _get_this_sessioninfo(session_id):
    for s in system.perspective.getSessionInfo():
        if s.get('id') == session_id:
            return s
    return {}

try:
    session_id = self.session.props.id

    sinfo = _get_this_sessioninfo(session_id)
    client_ip    = sinfo.get('clientAddress', '') or ''
    user_agent   = sinfo.get('userAgent', '') or ''
    page_url     = sinfo.get('pageUrl', sinfo.get('url', '')) or ''
    query_params = sinfo.get('queryParams', {}) or {}

    device_id = self.session.props.device.identifier  # 👈 huella digital

    logger.info("=== Station Debug ===")
    logger.info("SessionId: %s" % session_id)
    logger.info("DeviceId:  %s" % device_id)
    logger.info("Client IP: %s" % client_ip)
    logger.info("UserAgent: %s" % user_agent)
    logger.info("Page URL:  %s" % page_url)
    logger.info("QueryParams: %s" % system.util.jsonEncode(query_params))

except Exception as e:
    logger.error("Error obteniendo datos de sesión: %s" % e)
